struct PendingLike: Hashable {
    let postID: String
}

struct MutationQueue {
    var items: [PendingLike] = []
    mutating func enqueue(_ item: PendingLike) {
        if !items.contains(item) { items.append(item) }
    }
}

var queue = MutationQueue()
queue.enqueue(PendingLike(postID: "a1"))
queue.enqueue(PendingLike(postID: "a1"))
queue.enqueue(PendingLike(postID: "b2"))
print(queue.items.map(\.postID).joined(separator: ","))

