struct FeedPage: Sendable {
    let items: [String]
    let nextCursor: String?
}

protocol FeedRepo: Sendable {
    func load(cursor: String?) async -> FeedPage?
}

struct LocalCacheRepo: FeedRepo {
    func load(cursor: String?) async -> FeedPage? {
        cursor == nil ? FeedPage(items: ["p1", "p2"], nextCursor: "c2") : nil
    }
}

func fetchFeed(isOnline: Bool, cache: FeedRepo) async -> String {
    if !isOnline, let cached = await cache.load(cursor: nil) {
        return "\(cached.items.count):\(cached.nextCursor ?? "end")"
    }
    return isOnline ? "remote" : "empty"
}

let repo = LocalCacheRepo()
print(await fetchFeed(isOnline: false, cache: repo))
